 }

+export interface EdgeWorkerSession {
+  sessionId: string;
+  userId: string;
+  token: string;
+}
+
+const SESSION_SECRET = process.env.SESSION_SECRET || "dev-secret-key";
+
+const signSessionId = (id: string): string => {
+  const signature = createHmac("sha256", SESSION_SECRET).update(id).digest("hex");
+  return `${id}.${signature}`;
+};
+
+export const verifySessionToken = (token: string): string | null => {
+  const [id, signature] = token.split(".");
+  if (!id || !signature) return null;
+
+  const expectedSignature = createHmac("sha256", SESSION_SECRET)
+    .update(id)
+    .digest("hex");
+  if (signature !== expectedSignature) return null;
+
+  if (isSessionRevoked(id)) return null;
+
+  return id;
+};
+
+const revokedSessions = new Set<string>();
+
+const isSessionRevoked = (id: string): boolean => {
+  return revokedSessions.has(id);
+};
+
 export const loadSession = async (id: string): Promise<Session | null> => {
