     "SELECT id, user_id, revoked_at FROM sessions WHERE id = $1",
@@ -16,6 +50,24 @@ export const loadSession = async (id: string): Promise<Session | null> => {
   return { id: row.id, userId: row.user_id, revokedAt: row.revoked_at };
 };

+export const createSession = async (userId: string): Promise<EdgeWorkerSession> => {
+  const sessionId = randomUUID();
+  await pool.query(
+    "INSERT INTO sessions (id, user_id) VALUES ($1, $2)",
+    [sessionId, userId],
+  );
+  return {
+    sessionId,
+    userId,
+    token: signSessionId(sessionId),
+  };
+};
+
 export const revokeSession = async (id: string): Promise<void> => {
+  revokedSessions.add(id);
   await pool.query("UPDATE sessions SET revoked_at = now() WHERE id = $1", [id]);
 };
+
+export const getRevokedSessions = (): string[] => {
+  return Array.from(revokedSessions);
+};
